void opeu_supply_reset(uint8_t ds[65536]) {
  uint8_t a;
  for (a = 0; a < 12; ++a) {
    CLEAR_SUMS(a);
    CLEAR_AVERAGES(a);
    SET_SLOT_TYPE(SLOT_AT(a), 0xff);
    SET_TOTAL(0);
    SET_AMOUNTS(a, 0);
    SET_OTHERS(a, 0);
    SET_SLOT_AMOUNT(SLOT_AT(a), 0);
    SET_SLOT_OTHER(SLOT_AT(a), 0);
  }
  for (a = 0; a < 6; ++a) {
    SET_SLOT_TYPE(SPARE_AT(a), 0xff);
    SET_SLOT_AMOUNT(SPARE_AT(a), 0);
    SET_SLOT_OTHER(SPARE_AT(a), 0);
  }
}

